fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    // Ensure the input constraints
    assert_eq!(
        arr.len(),
        mask.len(),
        "The mask must have the same length as the array"
    );
    assert!(
        !vals.is_empty(),
        "The replacement values array must be non-empty"
    );

    let mut result = Vec::with_capacity(arr.len());
    let mut next_repl = 0;
    let repl_len = vals.len();

    for (a, m) in arr.into_iter().zip(mask.into_iter()) {
        if m {
            // Place the next replacement value (cyclically)
            result.push(vals[next_repl]);
            next_repl = (next_repl + 1) % repl_len;
        } else {
            // Keep the original value
            result.push(a);
        }
    }

    result
}

